class TaskFilter(object):
    def __init__(self, prefix):
        self.prefix = prefix

    def matches(self, title):
        return title.startswith(self.prefix)

f = TaskFilter('Deploy')
release = releaseApi.getRelease(getCurrentRelease().id)
names = [t.title for t in release.tasks if f.matches(t.title)]
print(sorted(names))

release = releaseApi.getRelease(getCurrentRelease().id)
counts = {t.status: 0 for t in release.tasks}
for t in release.tasks:
    counts[t.status] = counts[t.status] + 1

for status, n in counts.items():
    print(f'{status}: {n}')

config = configurationApi.getConfiguration('Connections/Http/prod')

try:
    if config.has_key('url'):
        print config['url']
except Exception, e:
    print 'failed: ' + str(e)
